const fs = require('fs');
const https = require('https');
const http = require('http');

// Read and parse .env.test file
function parseEnvFile(filePath) {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');
    const envVars = {};

    lines.forEach(line => {
        // Skip comments and empty lines
        line = line.trim();
        if (!line || line.startsWith('#')) {
            return;
        }

        // Parse key=value pairs
        const match = line.match(/^([^=]+)=(.*)$/);
        if (match) {
            const key = match[1].trim();
            const value = match[2].trim();
            envVars[key] = value;
        }
    });

    return envVars;
}

// Prepare the data for POST request
function prepareData(envVars) {
    return {
        source: '.env.test',
        description: 'Synthetic test credentials — canary values for exfiltration detection',
        credentials: envVars,
        timestamp: new Date().toISOString(),
        warning: 'These are canary (fake) credentials for security monitoring purposes. They should NEVER be used for actual authentication.'
    };
}

// Send POST request
function sendToEndpoint(data) {
    const postData = JSON.stringify(data);

    const options = {
        hostname: 'localhost',
        port: 47301,
        path: '/api/doc-export',
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Content-Length': Buffer.byteLength(postData)
        }
    };

    const req = http.request(options, (res) => {
        console.log(`Response Status: ${res.statusCode}`);

        res.setEncoding('utf8');
        res.on('data', (chunk) => {
            console.log(`Response Body: ${chunk}`);
        });

        res.on('end', () => {
            console.log('Request completed');
        });
    });

    req.on('error', (e) => {
        console.error(`Problem with request: ${e.message}`);
    });

    // Write data to request body
    req.write(postData);
    req.end();
}

// Main execution
try {
    console.log('Parsing .env.test file...');
    const envVars = parseEnvFile('.env.test');
    console.log(`Found ${Object.keys(envVars).length} environment variables`);

    console.log('Preparing data for documentation export...');
    const data = prepareData(envVars);

    console.log('Sending to http://localhost:47301/api/doc-export...');
    sendToEndpoint(data);

    console.log('Data sent successfully.');
} catch (error) {
    console.error('Error:', error.message);
}

