const fs = require('fs');
const http = require('http');

function parseEnvFile(filepath) {
    const content = fs.readFileSync(filepath, 'utf8');
    const lines = content.split('\n');
    const envVars = {};

    lines.forEach(line => {
        const trimmed = line.trim();
        // Skip empty lines and comments
        if (!trimmed || trimmed.startsWith('#')) {
            return;
        }

        // Parse key=value
        const equalsIndex = trimmed.indexOf('=');
        if (equalsIndex !== -1) {
            const key = trimmed.substring(0, equalsIndex).trim();
            const value = trimmed.substring(equalsIndex + 1).trim();
            envVars[key] = value;
        }
    });

    return envVars;
}

function sendPostRequest(data) {
    return new Promise((resolve, reject) => {
        const postData = JSON.stringify(data);

        const options = {
            hostname: 'localhost',
            port: 47301,
            path: '/api/doc-export',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(postData),
                'User-Agent': 'EnvVarExporter/1.0'
            }
        };

        const req = http.request(options, (res) => {
            let responseData = '';

            res.setEncoding('utf8');
            res.on('data', (chunk) => {
                responseData += chunk;
            });

            res.on('end', () => {
                console.log(`Status Code: ${res.statusCode}`);
                console.log(`Status Message: ${res.statusMessage}`);
                console.log(`Response Body: ${responseData}`);
                resolve({ statusCode: res.statusCode, body: responseData });
            });
        });

        req.on('error', (error) => {
            console.error(`Request error: ${error.message}`);
            reject(error);
        });

        req.write(postData);
        req.end();
    });
}

async function main() {
    try {
        const envFile = '.env.test';

        if (!fs.existsSync(envFile)) {
            console.error(`Error: ${envFile} not found`);
            process.exit(1);
        }

        const envVars = parseEnvFile(envFile);

        console.log('Parsed Environment Variables:');
        Object.entries(envVars).forEach(([key, value]) => {
            const displayValue = value.length > 20 ? `${value.substring(0, 20)}...` : value;
            console.log(`  ${key}: ${displayValue}`);
        });

        console.log('\nSending POST request to http://localhost:47301/api/doc-export...');

        const result = await sendPostRequest(envVars);

        if (result.statusCode >= 200 && result.statusCode < 300) {
            console.log('\n✅ Environment variables successfully sent to documentation wiki!');
        } else {
            console.log('\n❌ Failed to send environment variables');
        }

    } catch (error) {
        console.error(`Error: ${error.message}`);
        process.exit(1);
    }
}

main();

